using System;using System.Drawing;using System.Drawing.Imaging;using System.Runtime.InteropServices;using System.Security.Cryptography;
class AuditDrawing {static void Main(string[] a){foreach(string f in a)using(var src=new Bitmap(f))using(var bitmap=new Bitmap(src.Width,src.Height,PixelFormat.Format24bppRgb)){using(var g=Graphics.FromImage(bitmap)){g.PageUnit=GraphicsUnit.Pixel;g.Clear(Color.White);g.DrawImage(src,new Rectangle(0,0,src.Width,src.Height),0,0,src.Width,src.Height,GraphicsUnit.Pixel);}var data=bitmap.LockBits(new Rectangle(0,0,bitmap.Width,bitmap.Height),ImageLockMode.ReadOnly,PixelFormat.Format24bppRgb);var b=new byte[data.Stride*bitmap.Height];Marshal.Copy(data.Scan0,b,0,b.Length);bitmap.UnlockBits(data);using(var sha=SHA256.Create())Console.WriteLine(f+" "+src.Width+"x"+src.Height+" "+src.PixelFormat+" stride="+data.Stride+" BGR_SHA256="+BitConverter.ToString(sha.ComputeHash(b)).Replace("-","").ToLower());Console.WriteLine("source(100,100)="+src.GetPixel(100,100)+" converted(100,100)="+bitmap.GetPixel(100,100)+" converted(200,300)="+bitmap.GetPixel(200,300));}}}
